function updateStock(initialStock, received, shipped) {
  let stock = initialStock;
  stock = stock + received;
  stock = initialStock - shipped;
  return stock;
}

function sumWeights(firstText, secondText) {
  const first = Number(firstText);
  const second = secondText;
  return first + second;
}

function seatMessage(roomName, seatsLeft) {
  return '${roomName} has ${seatsLeft} empty seats.';
}

function printCost(pagePrice, pages, bindingFee) {
  return (pagePrice + bindingFee) * pages;
}

function ungroupedCount(volunteers, groupSize) {
  return volunteers / groupSize;
}

function meetsScore(score, minimumScore) {
  return score > minimumScore;
}

function canEnterHall(isOpen, hasTicket, hasStaffPass) {
  return isOpen && hasTicket || hasStaffPass;
}
